style.css:
div[data-e2e="recommend-list-item-container"] {
    display: none;
}

body::before {
    content: "TikTok giúp mày giàu lên hay chỉ giúp mày quên deadline? ?";
    position: fixed;
    top: 40%;
    left: 50%;
    transform: translate(-50%, -50%);
    font-size: 30px;
    font-weight: bold;
    color: white;
    background: black;
    padding: 20px;
    border-radius: 10px;
    z-index: 9999;
}
div[role="feed"] {
    display: none;
}

html {
    filter: blur(8px);
}
